// The three explainers for the Subject Vocabulary Standard pages. Each makes
// one idea land, with the accent colour reserved for its focal element.
// Generated by explainers.mjs --standard subject-vocabulary.

import { W, svg, box, ellipse, arrow, text, onAccent, highlight, numbered, starPerson, checkMark } from './sketch.mjs';

const standard = 'Subject Vocabulary Standard';
const title = (t) => text(W / 2, 92, t, { size: 52, weight: 700 });
const solidAccent = { fill: 'accent', fillStyle: 'solid', stroke: 'accent' };

// 1. Purpose: one shared set of abilities, each repository's own words beneath
// it. Focal is the shared core.
const purpose = svg({
  standard,
  title: 'Why a subject vocabulary standard',
  desc: 'A shared core of abilities, such as Traceability, that every repository can use in front-matter subject. Each repository adds its own themes and components beneath them, or replaces the core with its own set, so work from many repositories rolls up under the same promises.',
  body: [
    title('Why a subject vocabulary?'),
    ellipse(800, 300, 760, 230, solidAccent),
    onAccent(800, 280, 'One shared core of abilities', { size: 38, weight: 700 }),
    onAccent(800, 330, 'ability:traceability, ability:governability ...', { size: 24 }),
    box(150, 560, 400, 150), text(350, 615, 'Repository A', { size: 30, weight: 700 }), text(350, 660, 'theme:dashboard-ux', { size: 22 }),
    box(600, 560, 400, 150), text(800, 615, 'Repository B', { size: 30, weight: 700 }), text(800, 660, 'theme:value-reporting', { size: 22 }),
    box(1050, 560, 400, 150), text(1250, 615, 'Repository C', { size: 30, weight: 700 }), text(1250, 660, 'its own private set', { size: 22 }),
    arrow(350, 560, 560, 410), arrow(800, 560, 800, 418), arrow(1250, 560, 1040, 410, { dashed: true }),
    text(1250, 750, 'matched to the core', { size: 20 }),
    highlight(420, 845, 760, 56),
    text(800, 883, 'Work rolls up under the same promises', { size: 28 })
  ].join('\n')
});

// 2. Anatomy: one concept. Focal is the promise, the definition.
const rows = [
  { y: 175, h: 80, label: '"notation"', note: 'What you write: ability:traceability', side: 'left' },
  { y: 270, h: 80, label: '"prefLabel"', note: 'What people read: Traceability', side: 'right' },
  { y: 365, h: 200, label: '"definition"', note: 'The promise it makes', side: 'left', focal: true },
  { y: 580, h: 80, label: '"altLabel", "hiddenLabel"', note: 'Other names and suggester hints', side: 'right' },
  { y: 675, h: 80, label: '"broader", "exactMatch"', note: 'Where it rolls up', side: 'left' },
  { y: 770, h: 80, label: '"scopeNote", "audience"', note: 'What it is not; who sees it', side: 'right' }
];
const anatomy = svg({
  standard,
  title: 'Anatomy of a concept',
  desc: 'A concept is a W3C SKOS concept in plain JSON: the notation written in subject, a display label, the promise it makes to the person using the product, other names and hidden suggester hints, where it rolls up, and a scope note saying what it is not.',
  body: [
    title('Anatomy of a concept'),
    box(540, 150, 520, 720),
    ...rows.map((r) => [
      r.focal ? box(565, r.y, 470, r.h, solidAccent) : box(565, r.y, 470, r.h),
      r.focal
        ? onAccent(800, r.y + 70, r.label, { size: 34, weight: 700 }) + onAccent(800, r.y + 125, ['You can follow any piece of work', 'back to the question that started it'], { size: 22, lineHeight: 1.4 })
        : text(800, r.y + r.h / 2 + 9, r.label, { size: 24 }),
      r.side === 'left'
        ? text(480, r.y + r.h / 2 + 8, r.note, { size: r.focal ? 28 : 22, anchor: 'end', weight: r.focal ? 700 : 400 }) + arrow(490, r.y + r.h / 2, 555, r.y + r.h / 2)
        : text(1120, r.y + r.h / 2 + 8, r.note, { size: 22, anchor: 'start' }) + arrow(1110, r.y + r.h / 2, 1045, r.y + r.h / 2)
    ].join('')),
    text(800, 940, 'Plain JSON keys, each a SKOS term', { size: 22 })
  ].join('\n')
});

// 3. Adopt: pin, add your own, a person accepts. Focal is the person.
const steps = [
  { x: 120, n: 1, head: 'Pin and vendor', sub: ['subject-vocabulary.json', 'names 0.9'] },
  { x: 500, n: 2, head: 'Add your own', sub: ['extend the core,', 'or replace it'] },
  { x: 880, n: 3, head: 'Suggest', sub: ['reasons for each,', 'never writes'] }
];
const adopt = svg({
  standard,
  title: 'Adopt the standard in three steps',
  desc: 'Pin a released version in docs/registers/subject-vocabulary.json and keep a copy of it, add your own themes and components or replace the core with your own set, and let a suggester propose subjects with reasons. A person accepts them; nothing writes a subject on its own.',
  body: [
    title('Adopt it in three steps'),
    ...steps.map((s) => [
      numbered(s.x + 150, 300, s.n),
      box(s.x, 360, 300, 230),
      text(s.x + 150, 420, s.head, { size: 28, weight: 700 }),
      text(s.x + 150, 480, s.sub, { size: 20 })
    ].join('')),
    arrow(425, 475, 495, 475), arrow(805, 475, 875, 475), arrow(1185, 475, 1245, 475),
    ellipse(1400, 475, 280, 220, solidAccent),
    onAccent(1400, 455, 'A person', { size: 34, weight: 700 }),
    onAccent(1400, 500, 'accepts', { size: 30, weight: 700 }),
    checkMark(1400, 545, 36, { stroke: 'paper' }),
    starPerson(1400, 660, 1), text(1400, 770, 'the review is the decision', { size: 22 }),
    highlight(470, 860, 660, 56),
    text(800, 898, 'Subjects are chosen, never imposed', { size: 28 })
  ].join('\n')
});

export const explainers = { purpose, anatomy, adopt };
